-- Moves shipping address columns from orders into order_addresses.
-- ~20 minutes on prod-sized data (staging snapshot).
CREATE TABLE order_addresses (order_id bigint PRIMARY KEY REFERENCES orders(id), line1 text, city text, state text, zip text);
INSERT INTO order_addresses SELECT id, ship_line1, ship_city, ship_state, ship_zip FROM orders;
ALTER TABLE orders DROP COLUMN ship_line1, DROP COLUMN ship_city, DROP COLUMN ship_state, DROP COLUMN ship_zip;
